<p class="page-intro">Aquí aparecen las solicitudes cuya siguiente decisión te corresponde.</p><section class="panel"><div class="panel-header"><h2>Solicitudes por revisar</h2></div><?php requestTable(rows("SELECT r.*,c.name category,c.family,u.name FROM requests r JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.user_id JOIN approvals a ON a.request_id=r.id AND a.revision=r.revision WHERE r.status='pending' AND a.status='waiting' AND a.assigned_user_id=? AND NOT EXISTS(SELECT 1 FROM approvals b WHERE b.request_id=a.request_id AND b.revision=a.revision AND b.step<a.step AND b.status='waiting') ORDER BY r.created_at",[$u['id']])); ?></section>
<?php if(hasRole($u,'subsecretary')): $cancels=[]; foreach(rows("SELECT r.*,c.name category,c.family,u.name FROM requests r JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.user_id WHERE r.status='cancel_pending'") as $r) { try { if($wf->approver('subsecretary',row('SELECT * FROM users WHERE id=?',[$r['user_id']]))===(int)$u['id']) $cancels[]=$r; } catch(DomainException){} } ?><section class="panel"><div class="panel-header"><h2>Cancelaciones por autorizar</h2></div><?php requestTable($cancels); ?></section><?php endif; ?>
